<?php
$is_edit = !empty($record['id']);
function gl_value($record, $key, $fallback = '') { return set_value($key, isset($record[$key]) ? $record[$key] : $fallback); }
$risk_values = json_decode(isset($record['risk_factors_json']) ? $record['risk_factors_json'] : '', true); if (!is_array($risk_values)) { $risk_values = array(); }
$posted_risks = $this->input->post('risk_factors', true); if (is_array($posted_risks)) { $risk_values = $posted_risks; }
$medications = json_decode(isset($record['medications_json']) ? $record['medications_json'] : '', true); if (!is_array($medications)) { $medications = array(); }
$posted_meds = $this->input->post('medications', true); if (is_array($posted_meds)) { $medications = $posted_meds; }
$types = array('poag' => 'POAG - Primary Open Angle', 'pacg' => 'PACG - Primary Angle Closure', 'ntg' => 'NTG - Normal Tension', 'secondary' => 'Secondary Glaucoma', 'congenital' => 'Congenital', 'suspect' => 'Glaucoma Suspect', 'oht' => 'Ocular Hypertension');
$risks = array('elevated_iop' => 'Elevated IOP', 'thin_cornea' => 'Thin Cornea', 'high_myopia' => 'High Myopia', 'diabetes' => 'Diabetes', 'hypertension' => 'Hypertension', 'migraine' => 'Migraine', 'sleep_apnea' => 'Sleep Apnea', 'steroid_use' => 'Steroid Use');
?>
