            <div class="form-group col-sm-4"><label>Severity <span class="text-danger">*</span></label><select class="form-control" name="severity" required><?php foreach (array('suspect' => 'Suspect', 'mild' => 'Mild', 'moderate' => 'Moderate', 'severe' => 'Severe', 'end_stage' => 'End Stage') as $key => $label) { ?><option value="<?php echo $key; ?>" <?php echo gl_value($record, 'severity', 'mild') === $key ? 'selected' : ''; ?>><?php echo $label; ?></option><?php } ?></select></div>
            <div class="form-group col-sm-4"><label>Diagnosis Date <span class="text-danger">*</span></label><input type="date" class="form-control" name="diagnosis_date" required value="<?php echo html_escape(gl_value($record, 'diagnosis_date', date('Y-m-d'))); ?>"></div>
            <div class="col-sm-12"><label class="checkbox-inline"><input type="checkbox" name="family_history" value="1" <?php echo gl_value($record, 'family_history') ? 'checked' : ''; ?>> Family history of glaucoma</label><hr><label>Risk Factors</label><div><?php foreach ($risks as $key => $label) { ?><label class="gl-risk"><input type="checkbox" name="risk_factors[]" value="<?php echo $key; ?>" <?php echo in_array($key, $risk_values, true) ? 'checked' : ''; ?>> <?php echo $label; ?></label><?php } ?></div></div>
        </div></div>
