                <div class="col-sm-6"><h4>Target IOP</h4><div class="row"><div class="form-group col-xs-6"><label>OD Target (mmHg)</label><input type="number" step="0.1" min="0" class="form-control" name="target_iop_od" value="<?php echo html_escape(gl_value($record, 'target_iop_od', 16)); ?>"></div><div class="form-group col-xs-6"><label>OS Target (mmHg)</label><input type="number" step="0.1" min="0" class="form-control" name="target_iop_os" value="<?php echo html_escape(gl_value($record, 'target_iop_os', 16)); ?>"></div></div></div></div>
        </div></div>
        <div class="box gl-form-box"><div class="box-header with-border"><h3 class="box-title"><i class="fa fa-eye text-blue"></i> Optic Nerve Assessment</h3></div><div class="box-body"><div class="row">
            <?php foreach (array('od' => 'Right Eye (OD)', 'os' => 'Left Eye (OS)') as $eye => $label) { ?><div class="col-sm-6"><div class="gl-eye"><h4><?php echo $label; ?></h4><div class="form-group"><label>Cup-to-Disc Ratio</label><input type="number" step="0.1" min="0" max="1" name="cdr_<?php echo $eye; ?>" class="form-control" value="<?php echo html_escape(gl_value($record, 'cdr_' . $eye, 0.3)); ?>"></div><div class="form-group"><label>Rim Thinning</label><select class="form-control" name="rim_thinning_<?php echo $eye; ?>"><?php foreach (array('none' => 'None', 'superior' => 'Superior', 'inferior' => 'Inferior', 'temporal' => 'Temporal', 'diffuse' => 'Diffuse') as $key => $text) { ?><option value="<?php echo $key; ?>" <?php echo gl_value($record, 'rim_thinning_' . $eye, 'none') === $key ? 'selected' : ''; ?>><?php echo $text; ?></option><?php } ?></select></div><label class="checkbox-inline"><input type="checkbox" name="disc_hemorrhage_<?php echo $eye; ?>" value="1" <?php echo gl_value($record, 'disc_hemorrhage_' . $eye) ? 'checked' : ''; ?>> Disc Hemorrhage</label><label class="checkbox-inline"><input type="checkbox" name="nfl_defect_<?php echo $eye; ?>" value="1" <?php echo gl_value($record, 'nfl_defect_' . $eye) ? 'checked' : ''; ?>> NFL Defect</label></div></div><?php } ?>
        </div></div></div>
        <div class="box gl-form-box"><div class="box-body"><div class="gl-heading"><h4><i class="fa fa-medkit text-blue"></i> Current Medications</h4><button type="button" id="addMedication" class="btn btn-default btn-sm"><i class="fa fa-plus"></i> Add Medication</button></div><div id="medicationRows"><?php foreach ($medications as $i => $med) { ?><div class="gl-med-row medication-row row"><div class="form-group col-sm-4"><label>Medication</label><input class="form-control" name="medications[<?php echo $i; ?>][name]" value="<?php echo html_escape($med['name']); ?>"></div><div class="form-group col-sm-2"><label>Dosage</label><input class="form-control" name="medications[<?php echo $i; ?>][dosage]" value="<?php echo html_escape($med['dosage']); ?>"></div><div class="form-group col-sm-2"><label>Frequency</label><select class="form-control" name="medications[<?php echo $i; ?>][frequency]"><?php foreach (array('qd','bid','tid','qhs') as $freq) { ?><option <?php echo $med['frequency'] === $freq ? 'selected' : ''; ?>><?php echo strtoupper($freq); ?></option><?php } ?></select></div><div class="form-group col-sm-2"><label>Eye</label><select class="form-control" name="medications[<?php echo $i; ?>][eye]"><?php foreach (array('OU','OD','OS') as $eye) { ?><option <?php echo $med['eye'] === $eye ? 'selected' : ''; ?>><?php echo $eye; ?></option><?php } ?></select></div><div class="col-sm-2"><button type="button" class="btn btn-danger btn-sm remove-med"><i class="fa fa-trash"></i></button></div></div><?php } ?></div>
            <div class="row"><div class="form-group col-sm-4"><label>Progression Status</label><select class="form-control" name="progression_status"><option value="stable" <?php echo gl_value($record, 'progression_status', 'stable') === 'stable' ? 'selected' : ''; ?>>Stable</option><option value="suspected_progression" <?php echo gl_value($record, 'progression_status') === 'suspected_progression' ? 'selected' : ''; ?>>Suspected Progression</option><option value="definite_progression" <?php echo gl_value($record, 'progression_status') === 'definite_progression' ? 'selected' : ''; ?>>Definite Progression</option></select></div><div class="form-group col-sm-4"><label>Next Visit</label><input type="date" class="form-control" name="next_visit" value="<?php echo html_escape(gl_value($record, 'next_visit')); ?>"></div><div class="form-group col-sm-12"><label>Clinical Notes</label><textarea class="form-control" rows="3" name="notes" placeholder="Additional clinical notes..."><?php echo html_escape(gl_value($record, 'notes')); ?></textarea></div></div>
