</div>
<script>(function($){var i=<?php echo count($medications); ?>;function row(n){return '<div class="gl-med-row medication-row row"><div class="form-group col-sm-4"><label>Medication</label><input class="form-control" name="medications['+n+'][name]" list="glaucomaDrops" placeholder="Latanoprost 0.005%"></div><div class="form-group col-sm-2"><label>Dosage</label><input class="form-control" name="medications['+n+'][dosage]" placeholder="1 drop"></div><div class="form-group col-sm-2"><label>Frequency</label><select class="form-control" name="medications['+n+'][frequency]"><option>QD</option><option>BID</option><option>TID</option><option>QHS</option></select></div><div class="form-group col-sm-2"><label>Eye</label><select class="form-control" name="medications['+n+'][eye]"><option>OU</option><option>OD</option><option>OS</option></select></div><div class="col-sm-2"><button type="button" class="btn btn-danger btn-sm remove-med"><i class="fa fa-trash"></i></button></div></div>';}$('#addMedication').click(function(){$('#medicationRows').append(row(i++));});$(document).on('click','.remove-med',function(){$(this).closest('.medication-row').remove();});})(jQuery);</script>
<datalist id="glaucomaDrops"><option>Latanoprost 0.005%</option><option>Timolol 0.5%</option><option>Brimonidine 0.2%</option><option>Dorzolamide 2%</option><option>Bimatoprost 0.01%</option><option>Travoprost 0.004%</option><option>Combigan</option><option>Cosopt</option><option>Simbrinza</option></datalist>
